import {reviewRoutes} from './native-review.mjs?v=period43';
const desk=document.createElement('aside');desk.id='native-review-desk';desk.setAttribute('aria-label','Native build review controls');desk.innerHTML=`<h2>Her Crown</h2><p>Native-build UI review</p><label>Screen or flow<select id="review-route">${reviewRoutes.map(([id,title])=>`<option value="${id}">${title}</option>`).join('')}</select></label><label>Content state<select id="review-state"><option value="loaded">Ready · your local data</option><option value="example">Example populated library</option><option value="empty">Empty</option><option value="loading">Loading</option><option value="offline">Offline</option><option value="error">Error / retry</option><option value="denied">Permission denied</option><option value="pending">Purchase pending</option><option value="cancelled">Purchase cancelled</option></select></label><label>Membership<select id="review-membership"><option value="free">Free reader</option><option value="active">Plus · active</option><option value="trial">Plus · trial ending</option><option value="grace">Plus · grace period</option><option value="expired">Expired</option></select></label><button id="review-open">Open screen</button><p class="review-note">All data stays in this browser. Auth, payments, AI responses and support delivery are simulated.</p><details><summary>What’s included</summary><p>Complete Bible chapters in KJV, BSB and WEB; four library sections; notes, studies, bookmarks, devotional detail, reading plans, progress, preferences, account screens, legal pages, and purchase states.</p><p>Community includes monthly voting and separate cause suggestions; data is simulated.</p></details><a href="NATIVE-PARITY.md" target="_blank">Screen inventory & limitations ↗</a>`;document.body.append(desk);
const style=document.createElement('style');style.textContent=`#native-review-desk{position:absolute;left:20px;top:86px;width:250px;padding:20px;background:#fff;border-radius:18px;max-height:calc(100dvh - 106px);overflow:auto;box-shadow:0 12px 28px -18px #18242b44;z-index:5}#native-review-desk h2{margin:0;font-size:23px;letter-spacing:-.5px}#native-review-desk p{font-size:12px;line-height:1.6;color:#62686a}#native-review-desk label{display:block;font-size:12px;font-weight:500;margin-top:22px}#native-review-desk select{display:block;min-height:44px;width:100%;margin-top:8px;border:1px solid #daddde;border-radius:8px;padding:7px;font:12px -apple-system,sans-serif;background:white;color:#222}#review-open{width:100%;margin-top:22px;min-height:44px;border:0;border-radius:24px;background:#20382c;color:white;font:500 13px -apple-system,sans-serif;cursor:pointer}#native-review-desk .review-note{font-size:11px;margin:20px 0}#native-review-desk details{font-size:12px;border-top:1px solid #eee;padding-top:16px}#native-review-desk summary{cursor:pointer}#native-review-desk a{display:block;font-size:11px;color:#315d47;margin-top:20px}.preview-stage{left:280px;right:280px}#gradient-editor{max-height:calc(100dvh - 112px);overflow:auto}.preview-header strong{font-size:16px}@media(max-width:1050px) and (min-width:700px){#gradient-editor{display:none}.preview-stage{right:0}}@media(max-width:699px){.preview-stage{left:0;right:0}#native-review-desk{position:relative;left:auto;top:auto;width:min(92%,400px);max-height:none;margin:calc(100dvh - 35px) auto 20px}#gradient-editor{margin:20px auto;max-height:none}.preview-header span{display:none}}`;document.head.append(style);
const frame=document.querySelector('#app-preview');function send(){frame.contentWindow.postMessage({type:'her-crown-review',route:document.querySelector('#review-route').value,scenario:document.querySelector('#review-state').value,membership:document.querySelector('#review-membership').value},location.origin);if(innerWidth<700)document.querySelector('.preview-stage').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'})}document.querySelector('#review-open').onclick=send;
document.querySelector('.preview-header strong').textContent='Her Crown';document.querySelector('.device-note').textContent='Local UI review · no live transactions';
// Match the phone fit to the extra desktop review pane.
function refit(){const left=innerWidth>=700?280:0,right=innerWidth>=1051?280:0;document.documentElement.style.setProperty('--scale',Math.min((innerWidth-left-right-32)/458,(innerHeight-88)/974,1))}addEventListener('resize',refit);refit();

document.querySelector('#preview-membership').onclick=()=>{document.querySelector('#review-route').value='paywall';send()};
const mobileStyle=document.createElement('style');mobileStyle.textContent=`@media(max-width:699px){body{display:flex;flex-direction:column;height:auto;min-height:100dvh;overflow:auto}.preview-header{order:0;flex:none}.preview-stage{position:relative;inset:auto;height:calc(100dvh - 62px);width:100%;order:1;flex:none}#native-review-desk{order:2;position:relative;inset:auto;margin:20px auto;width:min(92%,400px)}#gradient-editor{order:3;position:relative;inset:auto;margin:0 auto 28px;width:min(92%,400px)}}`;document.head.append(mobileStyle);

// Studio shortcuts belong to this isolated preview only.
const studioPanel=document.querySelector('#gradient-editor');studioPanel.setAttribute('aria-label','Verse studios');studioPanel.innerHTML=`<h2>Verse studios</h2><p>Make a verse feel like your own.</p><button class="studio-launch" data-studio="snapshot-studio">Snapshot Studio ↗</button><button class="studio-launch" data-studio="widget">Widget Studio ↗</button><p id="studio-launch-note">Snapshot: Share verse → Snapshot Studio.<br><br>Widget: Settings → Widget Studio.<br><br>Designs and photos save locally. This preview does not install a Home Screen widget.</p>`;
const studioStyle=document.createElement('style');studioStyle.textContent='.studio-launch{display:block;width:100%;padding:12px;margin:12px 0;background:#111;color:#fff;border:0;border-radius:12px;min-height:44px;cursor:pointer}#studio-launch-note{font-size:12px;line-height:1.65}';document.head.append(studioStyle);
for(const b of studioPanel.querySelectorAll('[data-studio]'))b.onclick=()=>{if(frame.contentDocument.querySelector('.verse-studio[open]')){document.querySelector('#studio-launch-note').textContent='Use Done or the back button to close the current studio first.';return;}document.querySelector('#review-route').value=b.dataset.studio;send();};
let studioLaunched=false;function autoStudio(){if(studioLaunched)return;const which=new URLSearchParams(location.search).get('studio');if(!['snapshot','widget'].includes(which))return;studioLaunched=true;document.querySelector('#review-route').value=which==='snapshot'?'snapshot-studio':'widget';send();}frame.addEventListener('load',autoStudio);if(frame.contentDocument?.readyState==='complete')autoStudio();

const touchLinks=document.createElement('div');touchLinks.className='studio-touch-links';touchLinks.innerHTML='<a href="index.html?build=story2&studio=snapshot" target="_blank">Open full-screen Snapshot ↗</a><a href="index.html?build=story2&studio=widget" target="_blank">Open full-screen Widget ↗</a><p>Use full-screen on a phone for actual-size touch controls.</p>';studioPanel.append(touchLinks);const touchStyle=document.createElement('style');touchStyle.textContent='.studio-touch-links{border-top:1px solid #eee;margin-top:20px;padding-top:12px}.studio-touch-links a{display:block;padding:10px 0;font-size:12px;color:#111;text-decoration:underline;text-underline-offset:3px}';document.head.append(touchStyle);
